// B11 is block phhhh,phhhh of the secular matrix,
// <a,i,j,k,l|M|b,m,n,o,i1>, summed over the orders the scheme keeps.
func (el *Elem) B11(a, i, j, k, l, b, m, n, o, i1 int) float64 {
	var v float64
	if el.maxOrder[2] >= 0 {
		v += el.b11o0(a, i, j, k, l, b, m, n, o, i1)
	}
	if el.maxOrder[2] >= 1 {
		v += el.b11o1(a, i, j, k, l, b, m, n, o, i1)
	}
	return v
}
